CREATE FUNCTION public.retire_to_allocation(p_id uuid,p_until timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record;BEGIN IF auth.uid() IS NULL OR NOT(has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager access required';END IF;SELECT x.*,t.location_id INTO a FROM location_to_allocations x JOIN location_task_orders t ON t.id=x.task_order_id WHERE x.id=p_id AND x.effective_until IS NULL FOR UPDATE OF x;IF NOT FOUND OR p_until<a.effective_from THEN RAISE EXCEPTION 'Invalid active allocation or end time';END IF;IF a.personnel_id IS NOT NULL AND EXISTS(SELECT 1 FROM time_entries WHERE personnel_id=a.personnel_id AND location_id=a.location_id AND(is_locked OR invoice_id IS NOT NULL) AND clock_out_at>p_until) THEN RAISE EXCEPTION 'Locked or invoiced source cannot be reallocated';END IF;UPDATE location_to_allocations SET effective_until=p_until WHERE id=p_id;INSERT INTO audit_logs(user_id,user_email,action_type,resource_type,resource_id,changes_after) VALUES(auth.uid(),'to-allocation','to_allocation_retired','location_to_allocations',p_id,jsonb_build_object('effective_until',p_until));END $$;REVOKE ALL ON FUNCTION public.retire_to_allocation(uuid,timestamptz) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.retire_to_allocation(uuid,timestamptz) TO authenticated;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.assign_to_authorization(uuid,text,text,uuid,uuid)'::regprocedure) INTO d;d:=replace(d,'SELECT count(*) INTO cnt FROM location_to_allocations','IF EXISTS(SELECT 1 FROM location_to_allocations a JOIN location_task_orders t ON t.id=a.task_order_id WHERE t.location_id=o.location_id AND a.effective_until IS NULL AND a.effective_from>start_at AND ((p_person IS NOT NULL AND a.personnel_id=p_person) OR(p_asset IS NOT NULL AND a.asset_assignment_id=p_asset))) THEN RAISE EXCEPTION ''Cannot backdate across a later allocation'';END IF; SELECT count(*) INTO cnt FROM location_to_allocations');EXECUTE d;END $$;
CREATE FUNCTION public.guard_to_evidence_state() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND OLD.voided_at IS NULL AND NEW.voided_at IS NOT NULL THEN RETURN NEW;END IF;IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'TO sheet evidence cannot be rewritten';END IF;RETURN OLD;END $$;REVOKE ALL ON FUNCTION public.guard_to_evidence_state() FROM PUBLIC,anon,authenticated;CREATE TRIGGER to_evidence_no_rewrite BEFORE UPDATE ON public.location_to_sheet_entries FOR EACH ROW EXECUTE FUNCTION public.guard_to_evidence_state();